$ErrorActionPreference='Continue'
$root='D:\repository\数据湖\分析产出'; $arc="$root\归档_20261105"
function MoveGroup($files,$dest){
  foreach($f in $files){
    $src=Join-Path $root $f
    if(Test-Path -LiteralPath $src){ Move-Item -LiteralPath $src -Destination (Join-Path $arc $dest) -Force; Write-Output "moved [$dest] $f" }
    else { Write-Output "MISSING $f" }
  }
}
